 const technique=r.contentKind==='technique',variantGroup=!!r.variantGroup;
 $('#recipeKind').textContent=variantGroup?'PREPARACIONES':technique?'TÉCNICA':r.familyOnly?(r.contentKind==='family'?(familyNodePath(r.name).length>1?'SUBFAMILIA':'FAMILIA'):'CONSULTA'):'RECETA';
 $('#recipeTitle').textContent=r.name;
 $('#recipeMeta').textContent=variantGroup?'Elige el relleno para consultar su preparación':technique?'Guía de técnica y recomendaciones':r.familyOnly?(r.contentKind==='family'?familyDescription(r.name):'Familia / información'):[categoryLabelsFor(r),r.type,r.moment,r.single===undefined?'':(r.single?'Plato único':'Necesita acompañamiento'),r.linkStatus].filter(Boolean).join(' · ');
